def run(_context):
    import adsk.cam
    import adsk.fusion
    import adsk.core

    app = adsk.core.Application.get()
    doc = app.activeDocument

    # Get Design product
    des = adsk.fusion.Design.cast(doc.products.item(0))
    if des is None:
        print("Design is None, trying activeProduct")
        des = adsk.fusion.Design.cast(app.activeProduct)

    if des is not None:
        root = des.rootComponent
        print(f"Root component: {root}")
        # Try different property names for bodies
        for prop_name in ["bRepBodies", "bodies"]:
            try:
                bodies = getattr(root, prop_name)
                print(f"  {prop_name}: count={bodies.count}")
                body = bodies.item(0)
                print(f"  Body 0: {body.name}")

                # Get face 9
                faces = body.faces
                face9 = faces.item(9)
                print(f"  Face 9: area={face9.area}")
                break
            except AttributeError as e:
                print(f"  {prop_name}: AttributeError - {e}")
            except Exception as e:
                print(f"  {prop_name}: Error - {e}")
    else:
        print("Could not get Design product")

    # Alternative: get body through the CAM product's setup
    print("\n=== Alternative: CAM product ===")
    cam = adsk.cam.CAM.cast(doc.products.item(1))
    if cam:
        setup = cam.setups.itemByName("Setup1")
        if setup:
            print(f"Setup: {setup.name}")
            # Check if setup has a model
            try:
                model = setup.model
                print(f"  Model: {model}")
            except:
                print("  No model property")

            # Check setup parameters for stock model
            try:
                print(f"  Setup type: {type(setup)}")
                # List setup properties
                for attr in dir(setup):
                    if not attr.startswith('_') and not callable(getattr(setup, attr, None)):
                        try:
                            val = getattr(setup, attr)
                            if not callable(val):
                                print(f"    {attr}: {type(val).__name__}")
                        except:
                            pass
            except:
                pass

